function auth(setup){$('#app').innerHTML=`<main class="min-h-screen grid lg:grid-cols-2"><section class="hidden lg:flex flex-col justify-between bg-[#153f33] p-14 text-white"><div class="flex items-center gap-3">${icon('chat',32)}<span class="text-xl font-bold">WhatsApp Auto<span class="ml-3 text-xs font-normal text-[#9bb7a6]">PERSONAL WORKSPACE</span></span></div><div><span class="badge bg-white/10 text-[#bce8cd] mb-7">เรียบง่าย • เป็นส่วนตัว • อยู่ในเครื่องคุณ</span><h1 class="text-5xl font-semibold leading-[1.55] tracking-tight">ให้ทุกข้อความ<br>ไปถึงในเวลาที่ใช่<span class="text-[#98d6ac]">.</span></h1><p class="mt-7 max-w-md text-base leading-8 text-[#b1c8bb]">ส่งข้อความ จัดตารางงาน และเชื่อมต่อข้อมูล<br>ในพื้นที่ทำงานเดียวที่พร้อมให้คุณเริ่มต้น</p></div><p class="text-xs text-[#8eac9a]">LOCAL FIRST &nbsp; / &nbsp; NO CLOUD ACCOUNT REQUIRED</p></section><section class="flex min-h-screen items-center justify-center p-6"><div class="w-full max-w-sm"><div class="icon-box mb-7">${icon('shield',24)}</div><p class="mb-3 text-xs font-semibold tracking-widest text-[#6b9675]">ยินดีต้อนรับสู่พื้นที่ทำงานของคุณ</p><h2 class="text-3xl font-bold">${setup?'เริ่มต้นอย่างสบายใจ':'ยินดีต้อนรับกลับมา'}</h2><p class="mt-4 mb-8 leading-7 muted">${setup?'ตั้งรหัสผ่านสำหรับเข้าแอปในเครื่องนี้ ระบบเริ่มต้นด้วยโหมดสาธิต คุณลองใช้งานได้โดยยังไม่ต้องเชื่อมต่อ WhatsApp':'ใส่รหัสผ่านที่คุณตั้งไว้ เพื่อเข้าสู่พื้นที่ทำงานในเครื่องนี้'}</p><form id="auth-form" class="space-y-5"><div><label for="password">${setup?'สร้างรหัสผ่าน (อย่างน้อย 12 ตัวอักษร)':'รหัสผ่านของคุณ'}</label><input id="password" name="password" type="password" autocomplete="${setup?'new-password':'current-password'}" minlength="12" maxlength="128" required></div>${setup?'<div><label for="confirm">ยืนยันรหัสผ่าน</label><input id="confirm" name="confirm" type="password" autocomplete="new-password" minlength="12" required></div>':''}<button class="btn w-full py-3.5">${setup?'สร้างพื้นที่ทำงาน':'เข้าสู่ระบบ'}${icon('arrow',17)}</button><p id="auth-error" class="text-sm text-red-700" role="alert"></p></form><p class="mt-8 text-xs leading-6 muted">รหัสผ่านเก็บเป็นค่าแฮชในเครื่อง • API ใช้โทเคนแยกต่างหาก<br>เปิดใช้งานได้ที่ 127.0.0.1 เท่านั้น</p></div></section></main>`;$('#auth-form').onsubmit=async event=>{event.preventDefault();const data=new FormData(event.target);if(setup&&data.get('password')!==data.get('confirm')){$('#auth-error').textContent='รหัสผ่านทั้งสองช่องไม่ตรงกัน';return;}try{await api(setup?'/setup':'/login','POST',{password:data.get('password')});await boot();}catch(error){$('#auth-error').textContent=error.message;}};}
